CREATE OR REPLACE FUNCTION rc_history.assert_operational_id(p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE s text;BEGIN
 IF p_id IS NULL THEN RETURN;END IF;
 SELECT state INTO s FROM rc_history.identities WHERE exercise_id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'UNKNOWN_IDENTITY_NOT_REGISTERED' USING ERRCODE='42501';END IF;IF s<>'ACTIVE_ID' THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END$function$

CREATE OR REPLACE FUNCTION rc_history.guard_new_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE allocation rc_history.allocations%rowtype; actor uuid:=rc_history.request_actor();
BEGIN
 SELECT * INTO allocation FROM rc_history.allocations WHERE exercise_id=NEW.exercise_id;
 IF NOT FOUND OR allocation.actor_user_id IS DISTINCT FROM actor OR actor IS NULL OR rc_history.request_is_anonymous() THEN RAISE EXCEPTION 'ALLOCATION_REQUIRED' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.operator_profiles WHERE user_id=actor AND status='ACTIVE') THEN RAISE EXCEPTION 'ALLOCATION_UNAUTHORIZED' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.exercise_bootstrap_authorizations b WHERE b.id=allocation.bootstrap_id AND b.user_id=actor AND b.status='ACTIVE' AND b.expires_at>clock_timestamp() AND b.consumed_exercise_id IS NULL) THEN RAISE EXCEPTION 'BOOTSTRAP_AUTHORIZATION_REQUIRED' USING ERRCODE='42501';END IF;
 IF NEW.revision<>1 OR NEW.updated_by IS DISTINCT FROM actor OR NEW.state->'exerciseSession'->>'exerciseId' IS DISTINCT FROM NEW.exercise_id OR NEW.state->'exerciseSession'->>'lifecycleState' IS DISTINCT FROM 'READY' OR NEW.state->'exerciseSession'->>'simulationTimeSec' IS DISTINCT FROM '0' OR NEW.state->'exerciseSession'->>'speed' IS DISTINCT FROM '1' OR coalesce(NEW.state->'exerciseSession'->>'lastCommandId','') NOT LIKE 'PREPARE-%' THEN RAISE EXCEPTION 'BOOTSTRAP_INITIAL_READY_PROJECTION_REQUIRED' USING ERRCODE='42501';END IF;
 -- This binding is only an input to the canonical token claim, never authority itself.
 PERFORM pg_catalog.set_config('russicaptor.bootstrap_authorization_id',allocation.bootstrap_id::text,true);
 RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION rc_history.guard_runtime()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 DECLARE d jsonb; id text; oldid text; s text;
 BEGIN
 d:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF TG_TABLE_NAME='authorization_role_assignments' AND d->>'scope_type'<>'EXERCISE' AND (TG_OP<>'UPDATE' OR to_jsonb(OLD)->>'scope_type'<>'EXERCISE') THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 id:=coalesce(d->>'exercise_id',d->>'scope_id',d->>'consumed_exercise_id');
 IF id IS NULL AND TG_OP='UPDATE' AND TG_TABLE_NAME='authorization_role_assignments' THEN id:=to_jsonb(OLD)->>'scope_id';END IF;
 IF id IS NULL THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 IF TG_OP='UPDATE' THEN oldid:=coalesce(to_jsonb(OLD)->>'exercise_id',to_jsonb(OLD)->>'scope_id',to_jsonb(OLD)->>'consumed_exercise_id');IF oldid IS NOT NULL AND oldid IS DISTINCT FROM id THEN
 IF TG_TABLE_NAME<>'authorization_role_assignments' THEN RAISE EXCEPTION 'IDENTITY_RENAME_FORBIDDEN' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM rc_history.identities WHERE exercise_id IN(oldid,id) ORDER BY exercise_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rc_history.identities WHERE exercise_id=oldid AND state<>'ACTIVE_ID') THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END IF;END IF;
 IF NOT EXISTS(SELECT 1 FROM rc_history.identities WHERE exercise_id=id) THEN RAISE EXCEPTION 'UNKNOWN_IDENTITY_NOT_REGISTERED' USING ERRCODE='42501';END IF;
 SELECT state INTO STRICT s FROM rc_history.identities WHERE exercise_id=id FOR UPDATE;
 IF TG_OP='DELETE' THEN
   IF true THEN RAISE EXCEPTION 'ARCHIVE_DELETE_NOT_READY' USING ERRCODE='42501';END IF;
 ELSE IF s<>'ACTIVE_ID' THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END$function$

